  + '      return <Typography.CodeBlock withLineNumbers code={code} lang={lang} />;\n'
  + '    },\n'
  + '  };\n'
  + '\n'
  + '  return (\n'
  + '    <MdxJsProvider components={components}>{props.children}</MdxJsProvider>\n'
